const items = $input.all();

const icon = (ok) => ok
  ? '<span style="color:#1a7f37;font-weight:bold;">\u2714</span>'
  : '<span style="color:#c00;font-weight:bold;">\u2718</span>';

const rows = items.map(item => {
  const d = item.json;
  const checks = {
    Laenge:  d.fLaenge     > 0,
    Breite:  d.fBreite     > 0,
    Hoehe:   d.fHoehe      > 0,
    Gewicht: d.fArtGewicht > 0,
  };
  const hasIssue = Object.values(checks).some(v => !v);

  return {
    hasIssue,
    html: `<tr>
      <td>${d.cArtNr}</td>
      <td>${d.Artikelname || ''}</td>
      <td>${d.Webshops || ''}</td>
      <td style="text-align:center;">${icon(checks.Laenge)} ${d.fLaenge}</td>
      <td style="text-align:center;">${icon(checks.Breite)} ${d.fBreite} </td>
      <td style="text-align:center;">${icon(checks.Hoehe)} ${d.fHoehe} </td>
      <td style="text-align:center;">${icon(checks.Gewicht)} ${d.fArtGewicht}</td>
    </tr>`
  };
});

const problemRows = rows.filter(r => r.hasIssue);
const tableRows = problemRows.map(r => r.html).join('\n');

const html = `
<h2>JTL Artikelprüfung: Abmessungen &amp; Gewicht</h2>
<p>${problemRows.length} von ${rows.length} geprüften Artikeln (Bücherbüchse, LEAF, CINNA) haben fehlende Werte.</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px;">
  <thead style="background:#f2f2f2;">
    <tr>
      <th>ArtNr</th><th>Artikel</th><th>Webshop(s)</th>
      <th>Länge</th><th>Breite</th><th>Höhe</th><th>Gewicht</th>
    </tr>
  </thead>
  <tbody>
    ${tableRows || '<tr><td colspan="7">Keine Auffälligkeiten 🎉</td></tr>'}
  </tbody>
</table>`;

return [{ json: { html, count: problemRows.length, total: rows.length } }];

